INSERT INTO `poi_themes` (`id`, `code`, `name`, `description`, `icon`, `cover_url`, `group_name`, `sort_order`, `enabled`) VALUES
('17', 'river_source', '江河之源', '溯源而上，寻找中国主要江河的源头坐标', '💧', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/themes/river_source.jpg', '自然风光', '9', '1');
INSERT INTO `pois` (`id`, `name`, `category`, `lng`, `lat`, `adcode`, `address`, `summary`, `cover_url`, `hint_text`, `difficulty`, `source`, `used_count`, `verify_status`, `shape_type`, `radius_km`, `area_review`) VALUES
('4881', '长江之源', 'river_source', '91.05', '33.48', '632801', '青海省海西蒙古族藏族自治州格尔木市唐古拉山镇', '长江正源为沱沱河，发源于唐古拉山脉主峰格拉丹东雪山西南侧的姜根迪如冰川，冰川末端海拔约6500米。格拉丹东海拔6621米，冰川融水汇成万里长江的第一股细流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4881.jpg', '万里长江的起点，藏在唐古拉山脉的雪山之巅', '5', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4882', '黄河之源', 'river_source', '96.34', '34.49', '632723', '青海省玉树藏族自治州称多县扎朵镇', '1978年科学考察确认卡日曲为黄河正源，发源于巴颜喀拉山北麓各姿各雅峰。黄河水利委员会1985年认定约古宗列盆地为黄河源头并立碑，海拔约4500米。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4882.jpg', '母亲河的源头，在巴颜喀拉山北麓的约古宗列', '5', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4883', '澜沧江之源', 'river_source', '94.6956', '33.7086', '632722', '青海省玉树藏族自治州杂多县扎青乡', '澜沧江（湄公河上游）正源为扎阿曲，发源于唐古拉山脉北麓，位于青海玉树杂多县境内，源头海拔5200米以上。它出境后称湄公河，流经六国注入南海。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4883.jpg', '一条流经六国的国际大河，源头在青海玉树的雪山间', '5', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4884', '怒江之源', 'river_source', '92.2328', '32.73', '540624', '西藏自治区那曲市安多县帮麦乡', '怒江发源于唐古拉山脉南麓的桑曲，位于西藏那曲安多县境内，源头海拔约5400米。它南下穿过怒江大峡谷，出境后称萨尔温江，是我国水能最富集的河流之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4884.jpg', '南下入东南亚的大河，源头在唐古拉山南麓', '5', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4885', '雅鲁藏布江之源', 'river_source', '82.0556', '30.3683', '542521', '西藏自治区阿里地区普兰县霍尔镇', '雅鲁藏布江发源于喜马拉雅山脉北麓杰马央宗冰川，位于西藏阿里地区仲巴、普兰两县交界一带，源头海拔约5590米，是世界上海拔最高的大河，下游大峡谷为世界最深峡谷。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4885.jpg', '世界海拔最高的大河，源头在喜马拉雅山北麓', '5', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4886', '珠江之源', 'river_source', '103.986755', '25.846871', '530303', '云南省曲靖市沾益区炎方乡珠江源', '珠江正源位于云南曲靖沾益区马雄山，海拔2610米。珠江源景区立有『一水滴三江』碑，一泉之水分为南盘江、北盘江、牛栏江三支，汇成珠江水系。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4886.jpg', '一水滴三江，源头在云南曲靖的马雄山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4887', '松花江之源', 'river_source', '128.059214', '42.018229', '222426', '吉林省延边朝鲜族自治州安图县二道白河镇长白山天池(白头山天池)', '松花江有南北两源，北源即发源于长白山天池的第二松花江。天池海拔2189米，是我国最大的火山口湖，池水从天豁峰与龙门峰间缺口北流，滋养东北大地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4887.jpg', '长白山巅的火山口湖，是这条东北大河的起点', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4888', '辽河之源', 'river_source', '118.413227', '41.322091', '130881', '河北省承德市平泉市柳溪镇东大山', '辽河东源老哈河发源于河北承德平泉市七老图山脉的光头山，海拔1729米。老哈河与西拉木伦河汇合后始称辽河，南流入渤海，滋养东北平原南部。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4888.jpg', '七老图山脉的溪流，汇成东北平原南部的大河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4889', '汉江之源', 'river_source', '106.238907', '33.064133', '610726', '陕西省汉中市宁强县大安镇汉王山', '汉江发源于陕西汉中宁强县嶓冢山南麓，是长江最长的支流。源头有『嶓冢导漾』古迹，《禹贡》所载『嶓冢导漾，东流为汉』即出于此。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4889.jpg', '《禹贡》里『嶓冢导漾』的那座山，是长江最大支流之源', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4890', '渭河之源', 'river_source', '104.121', '35.124', '621123', '甘肃省定西市渭源县清源镇190乡道', '渭河发源于甘肃定西渭源县鸟鼠山，是黄河最大的支流。《尚书·禹贡》『鸟鼠同穴之山，渭水出焉』，渭河自此东流八百里，哺育了周秦汉唐的关中平原。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4890.jpg', '鸟鼠同穴之山，渭水出焉', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4891', '嘉陵江之源', 'river_source', '107.029', '34.173', '610330', '陕西省宝鸡市凤县平木镇', '嘉陵江发源于陕西宝鸡凤县代王山，是长江上游流域面积最大的支流。它切穿秦岭、巴山进入四川盆地，在重庆朝天门汇入长江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4891.jpg', '切穿秦岭入川的大江，源头在凤县', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4892', '淮河之源', 'river_source', '113.292593', '32.404256', '411330', '河南省南阳市桐柏县淮源镇西河堰桐柏山淮源风景名胜区', '淮河发源于河南南阳桐柏县桐柏山主峰太白顶北麓，海拔1140米。淮河与秦岭一线是我国重要的南北地理分界线，源头立有『淮源』石碑。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4892.jpg', '中国南北分界线的东端起点，源头在桐柏山', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4893', '钱塘江之源', 'river_source', '117.75146', '29.56501', '341022', '安徽省黄山市休宁县鹤城乡擂鼓峰', '1983年钱塘江河源考察队确认正源为新安江，源头在安徽休宁县鹤城乡六股尖（海拔1629.8米）东坡。溪流汇成新安江，经千岛湖入浙江称钱塘江，入杭州湾的钱塘潮被誉为天下第一潮。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4893.jpg', '新安江-千岛湖-钱塘江的起点，在皖南休宁六股尖', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4894', '闽江之源', 'river_source', '116.8167', '26.6356', '350430', '福建省三明市建宁县均口镇土楼上', '1991年福建省闽江办科考确定闽江正源，位于福建三明建宁县均口乡台田村严峰山西南坡，源头海拔约950米。台田溪汇入闽江后一路东流，经福州入海。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4894.jpg', '福建母亲河的源头，在三明的严峰山下', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4895', '赣江之源', 'river_source', '116.3314', '26.0226', '360735', '江西省赣州市石城县赣江源镇石城县赣江源景区', '2001年科学考察确定赣江正源为江西赣州石城县赣江源镇武夷山南段石寮岽的石寮河1号泉。赣江纵贯江西南北，经鄱阳湖注入长江，是江西的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4895.jpg', '江西母亲河的起点，在武夷山南段', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4896', '湘江之源', 'river_source', '112.066335', '25.203552', '431127', '湖南省永州市蓝山县湘江源瑶族乡湘江源景区停车点', '2011年第一次全国水利普查认定潇水为湘江正源，源头位于湖南永州蓝山县紫良瑶族乡野狗岭。湘江自南向北纵贯湖南，注入洞庭湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4896.jpg', '湖南母亲河的正源，是潇水，源头在蓝山县', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4897', '汾河之源', 'river_source', '112.1', '38.82', '140925', '山西省忻州市宁武县东寨镇忻五线芦芽山旅游度假区', '汾河发源于山西忻州宁武县东寨镇雷鸣寺泉，古称『汾源灵沼』，是山西最大的河流。汾河纵贯三晋大地七百余公里，在河津汇入黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4897.jpg', '汾源灵沼，山西最大河流的起点', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4898', '沅江之源', 'river_source', '107.36', '26.33', '522701', '贵州省黔南布依族苗族自治州都匀市绿茵湖街道红米冲', '沅江正源为摆洗河，发源于贵州都匀斗篷山南麓马鬃岭。斗篷山海拔1961米，是黔中最高峰。沅江下游入湖南称沅水，注入洞庭湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4898.jpg', '黔中最高峰斗篷山南麓，是这条入洞庭之河的源头', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4899', '乌江之源', 'river_source', '104.45', '26.98', '520526', '贵州省毕节市威宁彝族回族苗族自治县盐仓镇龙家山顶百草坪', '乌江正源为三岔河，发源于贵州毕节威宁县盐仓镇香炉山。乌江是长江上游南岸最大支流，纵贯贵州全境，在重庆涪陵注入长江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4899.jpg', '贵州第一大河的正源，在威宁的香炉山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4900', '岷江之源', 'river_source', '103.714179', '33.032597', '513224', '四川省阿坝藏族羌族自治州松潘县川主寺镇544国道', '岷江传统正源为四川阿坝松潘县弓杠岭，海拔约3700米，现为岷江源国家湿地公园核心区。岷江历史上曾被当作长江正源，南流经成都平原，在宜宾汇入长江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4900.jpg', '历史上曾被当作长江正源，起点在松潘弓杠岭', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4901', '雅砻江之源', 'river_source', '97.28', '33.8', '632723', '青海省玉树藏族自治州称多县清水河镇', '雅砻江是金沙江最大支流，发源于青海称多县巴颜喀拉山南麓，上源称扎曲，流经石渠、甘孜、雅江，在攀枝花汇入金沙江，水能资源极为丰富。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4901.jpg', '长江上游最大支流，发源于巴颜喀拉山南麓', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4902', '大渡河之源', 'river_source', '99.35', '33.65', '632624', '青海省果洛藏族自治州达日县建设乡', '大渡河是岷江最大支流，发源于巴颜喀拉山郭罗山南麓，河谷深切、水流湍急，在乐山汇入岷江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4902.jpg', '岷江最大支流，发源于郭罗山南麓', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4903', '白龙江之源', 'river_source', '102.63', '34.08', '513232', '四川省阿坝藏族羌族自治州若尔盖县红星镇郎木寺景区南停车场', '白龙江是嘉陵江上游主要支流，发源于甘川交界碌曲县郎木寺镇的西倾山郭尔莽梁北麓，流经迭部、舟曲、文县，在四川广元汇入嘉陵江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4903.jpg', '嘉陵江的支流，发源于郎木寺的西倾山北麓', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4904', '涪江之源', 'river_source', '103.85', '32.7', '513224', '四川省阿坝藏族羌族自治州松潘县黄龙乡', '涪江是嘉陵江主要支流，发源于川北岷山西部山地，流经绵阳、遂宁，在重庆合川汇入嘉陵江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4904.jpg', '发源于岷山西侧、流经绵阳的嘉陵江支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4905', '沱江之源', 'river_source', '103.85', '32.05', '510726', '四川省绵阳市北川羌族自治县青片乡', '沱江是长江上游主要支流之一，发源于龙门山西北麓，上源称湔江，流经成都平原东部，在泸州注入长江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4905.jpg', '发源于龙门山、在泸州入长江', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4906', '青衣江之源', 'river_source', '102.8', '30.55', '511827', '四川省雅安市宝兴县蜂桶寨乡', '青衣江是大渡河最大支流，发源于川西邛崃山、夹金山一带，流经雅安，在乐山汇入大渡河。流域多雨，是全国著名雨区。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4906.jpg', '发源于邛崃山区、流经雨城雅安的大渡河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4907', '丹江之源', 'river_source', '109.8', '33.95', '611002', '陕西省商洛市商州区麻街镇麻街', '丹江是汉江主要支流，发源于陕西商洛秦岭山区，流经丹凤、淅川汇入丹江口水库。丹江口水库是南水北调中线工程水源地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4907.jpg', '南水北调中线的水源之河，发源于商洛秦岭', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4908', '清江之源', 'river_source', '108.85', '30.25', '422802', '湖北省恩施土家族苗族自治州利川市凉雾乡打石沟', '清江是长江中游南岸主要支流，发源于湖北利川齐岳山一带，流经恩施、长阳，在宜都汇入长江，以水色清澈得名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4908.jpg', '因水清得名、发源于利川齐岳山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4909', '澧水之源', 'river_source', '109.85', '29.6', '430822', '湖南省张家界市桑植县河口乡沙弯槽', '澧水是湖南四大河流之一，发源于湘西北桑植县武陵山区，流经慈利、石门，在澧县注入洞庭湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4909.jpg', '湖南四水之一，发源于桑植武陵山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4910', '资水之源', 'river_source', '110.2', '26.25', '430529', '湖南省邵阳市城步苗族自治县丹口镇朝阳寨', '资水是湖南四大河流之一，传统正源出于广西资源县越城岭，向北流贯湖南中部，注入洞庭湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4910.jpg', '湖南四水之一，正源出于广西越城岭', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4911', '抚河之源', 'river_source', '116.3', '26.57', '361030', '江西省抚州市广昌县驿前镇池源', '抚河是鄱阳湖水系第二大河流，发源于江西广昌县驿前镇血木岭（灵华峰），北流经南丰、南城、抚州、南昌，注入鄱阳湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4911.jpg', '流经抚州入鄱阳湖，源头在广昌', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4912', '信江之源', 'river_source', '118.1', '28.9', '361123', '江西省上饶市玉山县三清乡三清山国家级旅游风景区', '信江是赣东北主要河流，发源于玉山、怀玉山区，流经上饶、鹰潭，注入鄱阳湖，中游有道教名山龙虎山。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4912.jpg', '发源于怀玉山、流经龙虎山的江西河流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4913', '曹娥江之源', 'river_source', '120.5', '29.05', '330727', '浙江省金华市磐安县安文街道长蛇山', '曹娥江是浙江东部独流入海的最大河流，发源于浙中丘陵，流经绍兴注入杭州湾。江名源自东汉孝女曹娥投江寻父的传说。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4913.jpg', '以孝女命名的浙东河流，注入杭州湾', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4914', '瓯江之源', 'river_source', '119.15', '27.85', '331181', '浙江省丽水市龙泉市屏南镇了望哨龙泉山景区', '瓯江是浙江第二大河，发源于浙南山区，流经丽水、温州入东海，上游龙泉以青瓷和宝剑闻名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4914.jpg', '温州的母亲河，发源于浙南山区', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4915', '飞云江之源', 'river_source', '119.65', '27.65', '330329', '浙江省温州市泰顺县罗阳镇坪岗', '飞云江是浙江八大河流之一，发源于浙南山区，流经文成、瑞安入东海，因飞云岭得名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4915.jpg', '浙江八大河流之一，在瑞安入东海', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4916', '晋江之源', 'river_source', '118.3', '25.75', '350526', '福建省泉州市德化县水口镇梓溪', '晋江是闽南最大河流，发源于闽中戴云山一带，流经三明、泉州，在泉州湾入海。江上的安平桥是中国现存最长的古代梁式石桥。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4916.jpg', '闽南最大河流，在泉州湾入海', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4917', '九龙江之源', 'river_source', '117.05', '25.1', '350802', '福建省龙岩市新罗区东城街道东宝路12-11号', '九龙江是福建第二大河，由北溪、西溪两大支流汇成，发源于闽西山区，流经龙岩、漳州，在厦门海沧入海。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4917.jpg', '福建第二大河，发源于闽西山区', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4918', '汀江之源', 'river_source', '116.6', '26.35', '350424', '福建省三明市宁化县济村乡黄柏', '汀江是客家母亲河，发源于福建宁化县，流经长汀、武平、上杭，入广东后称韩江。长汀古称汀州，是客家首府。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4918.jpg', '客家母亲河，发源于福建宁化', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4919', '榕江之源', 'river_source', '115.68', '23.18', '441523', '广东省汕尾市陆河县河口镇角子岭', '榕江是粤东第二大河流（仅次于韩江），发源于广东陆河县凤凰山，流经揭阳、汕头，在汕头牛田洋注入南海。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4919.jpg', '粤东第二大河流，在汕头牛田洋入海', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4920', '梅江之源', 'river_source', '115.2', '23.35', '441323', '广东省惠州市惠东县宝口镇上店子', '梅江是韩江主源，发源于广东紫金县武顿山（七星岽），上游称琴江，流经五华、兴宁、梅州，在大埔三河坝与汀江汇合后称韩江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4920.jpg', '韩江主源，发源于紫金武顿山，流经梅州', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4921', '东江之源', 'river_source', '115.55', '24.85', '360734', '江西省赣州市寻乌县晨光镇大帽嶂', '东江是珠江水系三大干流之一，发源于赣南寻乌县，流经河源、惠州，汇入珠江三角洲，是深圳、广州、香港的重要饮用水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4921.jpg', '珠江三大干流之一，发源于赣南寻乌', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4922', '右江之源', 'river_source', '104.95', '24.3', '532627', '云南省文山壮族苗族自治州广南县坝美镇安沙', '右江是珠江水系主干上游之一，发源于云贵高原，东南流经广西，在桂平与黔江汇合后称浔江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4922.jpg', '珠江源流之一，在广西桂平与黔江汇合', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4923', '北盘江之源', 'river_source', '104.25', '26.35', '530381', '云南省曲靖市宣威市来宾街道尖山丫口', '北盘江是珠江水系主干上游之一，发源于云贵高原，流经滇黔深切峡谷，在黔桂边界与南盘江汇合后称红水河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4923.jpg', '珠江源流之一，与南盘江汇合为红水河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4924', '牛栏江之源', 'river_source', '103.55', '27.05', '530621', '云南省昭通市鲁甸县江底镇上痴姑', '牛栏江是金沙江中游南岸支流，发源于云贵高原，流经云南东北部，在巧家一带汇入金沙江，峡谷落差巨大。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4924.jpg', '发源于云贵高原的金沙江支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4925', '漓江之源', 'river_source', '110.65', '25.85', '450329', '广西壮族自治区桂林市资源县中峰镇山中间', '漓江是珠江水系桂江上游支流，发源于广西兴安县猫儿山，流经桂林、阳朔，『桂林山水甲天下，阳朔山水甲桂林』的画卷沿江展开。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4925.jpg', '发源于猫儿山，流经桂林阳朔', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4926', '泾河之源', 'river_source', '106.2', '35.55', '640423', '宁夏回族自治区固原市隆德县陈靳乡笔尖山', '泾河是渭河最大支流，发源于宁夏泾源县六盘山，东南流至陕西高陵汇入渭河。成语『泾渭分明』即出自泾渭交汇之景。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4926.jpg', '渭河最大支流，『泾渭分明』典故出处', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4927', '北洛河之源', 'river_source', '108.1', '37.45', '610825', '陕西省榆林市定边县安边镇石学线', '北洛河是渭河主要支流之一，发源于陕北黄土丘陵地带，流经吴旗、蒲城，在大荔县汇入渭河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4927.jpg', '流经陕北黄土丘陵的渭河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4928', '洛河之源', 'river_source', '110.05', '34.15', '611021', '陕西省商洛市洛南县保安镇洞门', '洛河（南洛河）是黄河主要支流之一，发源于豫西熊耳山、华山一带，流经洛阳，在巩义汇入黄河。伊洛河流域孕育了河洛文明。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4928.jpg', '流经洛阳的黄河支流，发源于豫西山区', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4929', '伊河之源', 'river_source', '111.5', '33.85', '410324', '河南省洛阳市栾川县陶湾镇白岩跟', '伊河是洛河最大支流，发源于河南栾川县熊耳山南麓，流经嵩县、伊川，在偃师汇入洛河，伊洛合流后东注黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4929.jpg', '洛河最大支流，发源于栾川熊耳山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4930', '沙河之源', 'river_source', '112.65', '33.75', '410423', '河南省平顶山市鲁山县下汤镇017县道', '沙河是淮河最大支流，发源于河南嵩山伏牛山一带，流经平顶山、漯河、周口，与颍河汇合后入淮河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4930.jpg', '淮河最大支流，发源于嵩山伏牛山一带', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4931', '汝河之源', 'river_source', '112.4', '33.9', '410326', '河南省洛阳市汝阳县付店镇南圪垯', '汝河是淮河主要支流之一，发源于河南伏牛山区，流经汝州、平顶山、汝南，在豫东南注入淮河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4931.jpg', '发源于伏牛山、流经汝州的淮河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4932', '湟水之源', 'river_source', '101.0', '36.95', '632223', '青海省海北藏族自治州海晏县哈勒景蒙古族乡', '湟水是黄河上游最大支流，发源于青海海晏县日月山，流经西宁，在甘肃注入黄河。湟水谷地养育了青海大部分人口，被称为青海的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4932.jpg', '青海母亲河，发源于日月山', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4933', '洮河之源', 'river_source', '101.55', '34.8', '632324', '青海省黄南藏族自治州河南蒙古族自治县优干宁镇G0611张汶高速', '洮河是黄河上游主要支流之一，发源于甘青交界的西倾山区，流经岷县、临洮，在永靖刘家峡水库汇入黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4933.jpg', '发源于甘青交界山区的黄河上游支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4934', '沁河之源', 'river_source', '112.35', '36.95', '140431', '山西省长治市沁源县赤石桥乡', '沁河是黄河主要支流之一，发源于山西沁源县太岳山区，切穿太行山南段，在河南济源汇入黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4934.jpg', '发源于山西沁源、切穿太行山的黄河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4935', '漳河之源', 'river_source', '113.55', '37.25', '140723', '山西省晋中市和顺县喂马乡072乡道', '漳河是海河水系主要河流，发源于太行山区，有清、浊漳二源，流经安阳、邯郸。战国时西门豹治邺、引漳溉田的故事千古流传。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4935.jpg', '西门豹引水溉田的那条河，发源于太行山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4936', '滹沱河之源', 'river_source', '113.25', '39.15', '140924', '山西省忻州市繁峙县繁城镇大砂村', '滹沱河是海河水系主要河流，发源于山西繁峙县泰戏山一带，绕五台山南麓，切穿太行山流入河北平原。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4936.jpg', '发源于山西繁峙、流经五台山麓', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4937', '桑干河之源', 'river_source', '112.15', '39.0', '140927', '山西省忻州市神池县龙泉镇金山梁神池国家登山步道', '桑干河是海河水系永定河上游，发源于山西宁武县管涔山，流经大同盆地，在河北汇入官厅水库。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4937.jpg', '永定河的上游，发源于山西宁武', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4938', '无定河之源', 'river_source', '108.8', '37.45', '610824', '陕西省榆林市靖边县镇靖镇古城子', '无定河是黄河中游主要支流，发源于陕北定边一带，流经榆林，在清涧汇入黄河。唐诗『可怜无定河边骨』吟咏的正是此河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4938.jpg', '唐诗中吟咏的河流，在陕西清涧入黄河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4939', '大黑河之源', 'river_source', '111.4', '41.15', '150125', '内蒙古自治区呼和浩特市武川县可可以力更镇康油坊', '大黑河是黄河上游主要支流之一，发源于内蒙古高原，流经呼和浩特，在托克托县汇入黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4939.jpg', '流经呼和浩特的黄河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4940', '滦河之源', 'river_source', '116.85', '41.55', '130825', '河北省承德市隆化县郭家屯镇头道洼', '滦河是冀北最大河流，发源于河北丰宁县，流经承德、唐山注入渤海，是天津与冀东的重要水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4940.jpg', '发源于河北丰宁，天津的重要水源', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4941', '白河之源', 'river_source', '115.9', '41.65', '130724', '河北省张家口市沽源县闪电河乡275乡道', '白河是潮白河水系两大源流之一，发源于冀北山区，南流注入密云水库，是北京重要的饮用水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4941.jpg', '潮白河两大源流之一，注入密云水库', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4942', '潮河之源', 'river_source', '117.05', '41.2', '130826', '河北省承德市丰宁满族自治县石人沟乡', '潮河是潮白河水系两大源流之一，发源于河北滦平县，南流注入密云水库，与白河汇合后称潮白河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4942.jpg', '潮白河两大源流之一，发源于河北滦平', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4943', '淠河之源', 'river_source', '115.85', '31.75', '341524', '安徽省六安市金寨县梅山镇胡冲塘湾', '淠河是淮河主要支流之一，发源于大别山北麓金寨一带，流经六安，在寿县注入淮河，是淠史杭灌区的水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4943.jpg', '发源于大别山北麓的淮河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4944', '沂河之源', 'river_source', '118.2', '36.2', '370323', '山东省淄博市沂源县历山街道新城路', '沂河是鲁南最大河流，发源于沂蒙山区，流经临沂入江苏，是沂蒙革命老区的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4944.jpg', '发源于沂蒙山、流经临沂', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4945', '嫩江之源', 'river_source', '122.3', '51.2', '150785', '内蒙古自治区呼伦贝尔市根河市好里堡街道', '嫩江是松花江最大支流，发源于大兴安岭伊勒呼里山南麓，南流贯东北平原，在扶余一带汇入松花江，流域是重要商品粮基地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4945.jpg', '松花江最大支流，发源于大兴安岭', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4946', '牡丹江之源', 'river_source', '128.1', '43.8', '222403', '吉林省延边朝鲜族自治州敦化市额穆镇', '牡丹江是松花江主要支流，发源于长白山脉北段，流经镜泊湖、哈尔滨依兰，汇入松花江。镜泊湖是我国最大的高山堰塞湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4946.jpg', '发源于长白山、流经镜泊湖的松花江支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4947', '图们江之源', 'river_source', '128.5', '42.05', '222406', '吉林省延边朝鲜族自治州和龙市龙城镇', '图们江是中朝界河，发源于长白山脉东麓，向东流经延边，在珲春附近注入日本海（东海）。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4947.jpg', '中朝界河，发源于长白山东麓', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4948', '鸭绿江之源', 'river_source', '127.9', '41.9', '220621', '吉林省白山市抚松县漫江镇长白山国家级自然保护区', '鸭绿江是中朝界河，发源于长白山脉南麓，流经临江、集安、丹东，注入黄海。『雄赳赳，气昂昂，跨过鸭绿江』的歌曲家喻户晓。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4948.jpg', '中朝界河，发源于长白山南麓、流经丹东', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4949', '呼兰河之源', 'river_source', '128.9', '47.3', '230725', '黑龙江省伊春市大箐山县寒月林场', '呼兰河是松花江支流，发源于小兴安岭西南麓铁力市太平岭，流经铁力、庆安、绥化，在哈尔滨呼兰区汇入松花江。女作家萧红以河畔故乡为题材写下《呼兰河传》。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4949.jpg', '萧红笔下的河流，在哈尔滨汇入松花江', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4950', '西拉木伦河之源', 'river_source', '117.3', '43.35', '150425', '内蒙古自治区赤峰市克什克腾旗达来诺日镇喜鹊沟', '西拉木伦河是西辽河上游，发源于内蒙古克什克腾旗大兴安岭南端，流经科尔沁沙地。西辽河流域孕育了著名的红山文化。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4950.jpg', '西辽河的上游，发源于内蒙古克什克腾旗', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4951', '海拉尔河之源', 'river_source', '120.7', '49.1', '150724', '内蒙古自治区呼伦贝尔市鄂温克族自治旗大雁镇', '海拉尔河是额尔古纳河源流，发源于大兴安岭西麓，婉蜒流过呼伦贝尔草原，西流后与扎兰鄂罗木河相通始称额尔古纳河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4951.jpg', '额尔古纳河的源流，蜿蜒于呼伦贝尔草原', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4952', '黑河之源', 'river_source', '99.5', '38.3', '632222', '青海省海北藏族自治州祁连县野牛沟乡', '黑河是我国第二大内陆河，发源于祁连山区，向北流经张掖，最终注入额济纳旗居延海，是河西走廊的生命线。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4952.jpg', '发源于祁连山、流经张掖的内陆河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4953', '石羊河之源', 'river_source', '102.7', '37.2', '620623', '甘肃省武威市天祝藏族自治县抓喜秀龙镇大阳屲', '石羊河是河西走廊三大内陆河之一，发源于祁连山东段，流经武威，最终注入民勤青土湖，是阻止两大沙漠合拢的重要水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4953.jpg', '流经武威、消失于民勤的河西走廊河流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4954', '疏勒河之源', 'river_source', '97.8', '38.6', '632823', '青海省海西蒙古族藏族自治州天峻县苏里乡', '疏勒河是河西走廊三大内陆河之一，发源于祁连山脉西段疏勒南山与托来南山之间的疏勒脑（沙果林那穆吉木岭），流经青海天峻、甘肃肃北、玉门、瓜州，是古丝绸之路的重要补给水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4954.jpg', '发源于祁连山、流经玉门的内陆河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4955', '额尔齐斯河之源', 'river_source', '89.6', '47.55', '654322', '新疆维吾尔自治区阿勒泰地区富蕴县库尔特乡', '额尔齐斯河是我国唯一注入北冰洋的河流，发源于阿尔泰山南麓，向西北流经哈萨克斯坦、俄罗斯，成为鄂毕河最大支流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4955.jpg', '我国唯一注入北冰洋的河流', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4956', '特克斯河之源', 'river_source', '81.3', '43.15', '654026', '新疆维吾尔自治区伊犁哈萨克自治州昭苏县乌尊布拉克镇577国道', '特克斯河是伊犁河最大源流，发源于天山山脉，流经昭苏大草原，下游汇成伊犁河最终注入巴尔喀什湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4956.jpg', '伊犁河的主源流，流经昭苏大草原', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4957', '开都河之源', 'river_source', '84.1', '42.95', '652827', '新疆维吾尔自治区巴音郭楞蒙古自治州和静县巴音郭楞乡', '开都河是注入博斯腾湖的最大河流，发源于中天山山脉，流经巴音布鲁克大草原。《西游记》中的通天河相传即指此河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4957.jpg', '流经巴音布鲁克草原、注入博斯腾湖', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4958', '玛纳斯河之源', 'river_source', '85.8', '43.5', '652324', '新疆维吾尔自治区昌吉回族自治州玛纳斯县清水河哈萨克族乡', '玛纳斯河是天山北坡内陆河，发源于天山山脉，向北流淌滋养石河子绿洲。玛纳斯河流域是新疆重要的棉花产区。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4958.jpg', '天山北坡的河流，滋养石河子绿洲', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4959', '乌伦古河之源', 'river_source', '90.4', '46.9', '654325', '新疆维吾尔自治区阿勒泰地区青河县阿热勒镇', '乌伦古河发源于阿尔泰山南麓，流经富蕴县，注入乌伦古湖，是阿勒泰地区重要的灌溉水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4959.jpg', '发源于阿尔泰山南麓，注入乌伦古湖', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4960', '拉萨河之源', 'river_source', '90.95', '30.45', '540122', '西藏自治区拉萨市当雄县宁中乡杀嗡朗', '拉萨河是雅鲁藏布江中游主要支流，发源于念青唐古拉山南麓，流经拉萨市区，在曲水汇入雅鲁藏布江，被称为拉萨的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4960.jpg', '拉萨的母亲河，发源于念青唐古拉山', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4961', '尼洋河之源', 'river_source', '92.35', '29.85', '540421', '西藏自治区林芝市工布江达县加兴乡达木嘎', '尼洋河是雅鲁藏布江中下游主要支流，发源于念青唐古拉山西麓，流经工布江达、林芝，河谷森林茂密、风光秀丽。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4961.jpg', '发源于念青唐古拉山、流经林芝的雅江支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4962', '狮泉河之源', 'river_source', '81.81', '31.31', '542525', '西藏自治区阿里地区革吉县亚热乡邦果拉', '狮泉河（森格藏布）是印度河上游，发源于冈底斯山主峰冈仁波齐峰北面的冰川湖，流经狮泉河镇（阿里地区行政公署驻地），出境后称印度河，是阿里『四大河』之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4962.jpg', '阿里四大河之一，印度河的上游', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4986', '赤水河之源', 'river_source', '105.3', '27.55', '520502', '贵州省毕节市七星关区大银镇双树子', '赤水河是长江上游右岸支流，发源于云南镇雄县赤水镇，流经云贵川三省交界，在四川合江汇入长江。因''四渡赤水''闻名中外，也是茅台、郎酒等酱香白酒的酿造水源。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4986.jpg', '红军四渡赤水的那条河，也是茅台酒的水源', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4987', '柳江之源', 'river_source', '107.55', '25.8', '522726', '贵州省黔南布依族苗族自治州独山县百泉镇播落寨', '柳江是珠江水系西江第二大支流，发源于贵州独山县，流经广西三江、柳州，在象州汇入西江干流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4987.jpg', '流经柳州的西江支流，源头在贵州独山', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4988', '桂江之源', 'river_source', '110.4', '25.6', '450325', '广西壮族自治区桂林市兴安县溶江镇枫木坪', '桂江是珠江水系支流，发源于广西兴安县猫儿山，上游即著名的漓江，流经桂林、昭平，在梧州汇入西江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4988.jpg', '漓江的下游，流经桂林到梧州', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4989', '北江之源', 'river_source', '114.9', '25.4', '360722', '江西省赣州市信丰县嘉定镇胡里坑', '北江是珠江三大支流之一，发源于江西信丰县，流经广东南雄、韶关、清远，在三水汇入珠江三角洲。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4989.jpg', '珠江三大支流之一，流经韶关', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4990', '郁江之源', 'river_source', '105.0', '24.1', '532627', '云南省文山壮族苗族自治州广南县莲城镇350县道', '郁江是西江最大支流，发源于云南广南县，上源称驮娘江，流经广西百色、南宁，在桂平与黔江汇合后称浔江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4990.jpg', '西江最大支流，流经南宁', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4991', '修水之源', 'river_source', '114.5', '29.0', '360424', '江西省九江市修水县义宁镇良瑞佳园小区D11栋', '修水是鄱阳湖水系五大河流之一，发源于江西修水县西部山区，东流经武宁、永修，注入鄱阳湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4991.jpg', '鄱阳湖五大河之一，在江西西北部', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4992', '饶河之源', 'river_source', '117.7', '29.8', '341024', '安徽省黄山市祁门县塔坊镇上谢', '饶河是鄱阳湖水系河流，发源于安徽祁门县，上游称昌江，流经江西景德镇、鄱阳，注入鄱阳湖。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4992.jpg', '流经景德镇入鄱阳湖的河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4993', '青弋江之源', 'river_source', '117.9', '30.0', '341023', '安徽省黄山市黟县洪星乡石顶尖', '青弋江发源于安徽黟县黄山北麓，流经石台、泾县、南陵，在芜湖汇入长江，是皖南最大河流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4993.jpg', '发源于黄山北麓、在芜湖入长江的皖南大河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4994', '大汶河之源', 'river_source', '118.2', '36.0', '370323', '山东省淄博市沂源县中庄镇抱子沟', '大汶河是黄河下游最后一条大支流，发源于山东沂源县沂蒙山区，流经莱芜、泰安，在东平湖汇入黄河。大汶口文化即以此河命名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4994.jpg', '以大汶口文化闻名，在山东泰安入黄河', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4995', '浑河之源', 'river_source', '124.9', '42.1', '210423', '辽宁省抚顺市清原满族自治县清原镇刺毛果沟', '浑河是辽河支流，发源于辽宁清原县滚马岭，流经抚顺、沈阳，在海城与太子河汇合后入辽河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4995.jpg', '流经沈阳和抚顺的辽河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4996', '太子河之源', 'river_source', '124.1', '41.3', '210521', '辽宁省本溪市本溪满族自治县小市镇迎宾路', '太子河是辽河支流，发源于辽宁本溪县，流经本溪、辽阳、鞍山，在海城与浑河汇合。因燕太子丹逃亡于此而得名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4996.jpg', '因燕太子丹得名的辽东河流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4997', '绥芬河之源', 'river_source', '129.8', '43.3', '222424', '吉林省延边朝鲜族自治州汪清县东光镇图汪线', '绥芬河发源于吉林汪清县，流经黑龙江东宁，出境后入俄罗斯符拉迪沃斯托克附近海，是东北地区重要的跨界河流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4997.jpg', '流出国境入日本海的东北河流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4998', '甬江之源', 'river_source', '121.4', '29.65', '330213', '浙江省宁波市奉化区锦屏街道西直路', '甬江发源于浙江奉化市四明山东麓，上游称奉化江，流经宁波市区，在镇海注入东海，是宁波的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4998.jpg', '宁波的母亲河，在镇海入海', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('4999', '灵江之源', 'river_source', '120.5', '28.7', '331024', '浙江省台州市仙居县皤滩乡双岗尖', '灵江发源于浙江仙居县，上游称永安溪，流经临海市区，在椒江注入东海，是台州最大的河流。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/4999.jpg', '台州第一大河，在椒江入海', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5000', '万泉河之源', 'river_source', '110.0', '19.0', '469030', '海南省琼中黎族苗族自治县营根镇042乡道', '万泉河发源于海南琼中县五指山北麓，流经琼海，在博鳌入南海。歌曲《万泉河水清又清》使其广为人知。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5000.jpg', '歌曲里''水清又清''的那条海南河', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5001', '南渡江之源', 'river_source', '109.5', '19.2', '469025', '海南省白沙黎族自治县牙叉镇白沙陨石坑', '南渡江是海南第一大河，发源于海南白沙县南峰山，流经儋州、澄迈，在海口入琼州海峡。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5001.jpg', '海南第一大河，在海口入海', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5002', '拉林河之源', 'river_source', '127.2', '44.9', '230184', '黑龙江省哈尔滨市五常市五常镇民意乡环路', '拉林河是松花江右岸支流，发源于黑龙江五常市张广才岭，流经五常、双城，在哈尔滨上游汇入松花江。五常大米即产于此流域。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5002.jpg', '五常大米的产区河流，汇入松花江', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5003', '汤旺河之源', 'river_source', '129.5', '47.5', '230751', '黑龙江省伊春市金林区小昆仑林场', '汤旺河是松花江下游支流，发源于黑龙江伊春市小兴安岭，流经伊春市区，在汤原汇入松花江，两岸森林茂密。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5003.jpg', '小兴安岭中的河流，流经伊春', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5004', '安宁河之源', 'river_source', '102.2', '28.5', '513433', '四川省凉山彝族自治州冕宁县复兴镇高窑村', '安宁河是雅砻江支流，发源于四川冕宁县，南流经西昌、德昌，在米易汇入雅砻江，是凉山彝族自治州的母亲河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5004.jpg', '流经西昌的雅砻江支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5005', '窟野河之源', 'river_source', '109.8', '39.5', '150627', '内蒙古自治区鄂尔多斯市伊金霍洛旗阿勒腾席热镇阿成东线', '窟野河是黄河中游支流，发源于内蒙古伊金霍洛旗，流经陕西神木，在河口汇入黄河，流域煤炭资源极为丰富。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5005.jpg', '流经神木煤田的黄河支流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5006', '清水河之源', 'river_source', '106.2', '36.0', '640402', '宁夏回族自治区固原市原州区中河乡209乡道', '清水河是黄河支流，发源于宁夏固原市六盘山东麓，流经固原、同心，在中宁汇入黄河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5006.jpg', '发源于六盘山、在宁夏入黄河的河', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5007', '皖河之源', 'river_source', '116.3', '30.8', '340828', '安徽省安庆市岳西县中关镇杨坳老屋', '皖河是长江下游支流，发源于安徽岳西县大别山，流经潜山、怀宁，在安庆汇入长江。安徽省简称''皖''即源于此河。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5007.jpg', '安徽简称''皖''的来源河流', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('5008', '浠水之源', 'river_source', '115.5', '30.7', '421123', '湖北省黄冈市罗田县白莲河乡韩家冲', '浠水（又名兰溪）是长江中游支流，发源于湖北英山县大别山南麓，流经罗田、浠水，在兰溪镇汇入长江。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/5008.jpg', '大别山南麓的湖北河流，在兰溪入长江', '4', 'manual', '0', 'approved', 'point', '0.0', '1');
